import 'app_localization.dart';

/// Original Persian rendering for long devotional texts.
/// Arabic source text is preserved in Arabic mode; Quran quotations stay Arabic.
String persianContent(String source) {
  if (appLanguage.value != 'fa') return source;

  if (source.startsWith('بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيمِ')) {
    return '''به نام خداوند بخشنده مهربان
خدایا بر محمد و خاندان محمد درود فرست.

به زیارت سرور و مولایم، اباعبدالله الحسین (علیه‌السلام) می‌آیم؛ از سوی خودم و به نیابت از صاحب عصر و زمان، پدر و مادر و نیاکانم، فرزندم، خواهران و برادرانم، همسایگان و خویشاوندان و عزیزانم، و هر کس که مرا برای دعا و زیارت نایب خود قرار داده است، و نیز همه مردان و زنان مؤمن، زنده و درگذشته؛ برای تقرب به خدای متعال.''';
  }

  if (source.startsWith('السَّلَامُ عَلَيْكَ يَا أَبَا عَبْدِ اللهِ، السَّلَامُ عَلَيْكَ يَا ابْنَ رَسُولِ اللهِ')) {
    return '''سلام بر تو ای اباعبدالله؛ سلام بر تو ای فرزند رسول خدا؛ سلام بر تو ای فرزند امیرمؤمنان و سرور اوصیا؛ سلام بر تو ای فرزند فاطمه، سرور زنان جهان؛ سلام بر تو ای خون‌خواه خدا و فرزند خون‌خواه او، و ای یگانه‌ای که خون‌خواهی‌ات وانهاده شد. سلام بر تو و بر جان‌هایی که در آستانت فرود آمدند. تا زمانی که زنده‌ام و شب و روز برقرار است، سلام همیشگی خدا بر همه شما باد.

ای اباعبدالله، مصیبت تو بسیار بزرگ و سنگین شد؛ داغ تو بر ما و بر همه مسلمانان عظیم گشت و اندوه شهادتت در آسمان‌ها نیز بزرگ و جان‌سوز است. خدا لعنت کند مردمی را که پایه ستم و بیداد بر شما اهل‌بیت را بنا نهادند؛ و مردمی را که شما را از جایگاهتان کنار زدند و از منزلت‌هایی که خدا برایتان مقرر کرده بود دور ساختند؛ و مردمی را که شما را کشتند؛ و کسانی را که زمینه کشتن شما را فراهم کردند. من نزد خدا و شما از آنان و پیروان و همراهانشان بیزاری می‌جویم.

ای اباعبدالله، من با هر کس که با شما در صلح باشد در صلحم و تا روز قیامت با هر کس که با شما بجنگد در جنگم. خدا خاندان زیاد و خاندان مروان و همه بنی‌امیه و ابن‌مرجانه و عمر بن سعد و شمر و مردمی را که برای جنگ با تو آماده شدند لعنت کند. پدر و مادرم فدایت؛ مصیبت تو بر من بسیار بزرگ است. از خدایی که جایگاه تو را گرامی داشت و مرا به سبب تو ارجمند ساخت، می‌خواهم که خون‌خواهی تو را همراه پیشوایی یاری‌شده از خاندان محمد روزی‌ام کند.

خدایا، به برکت حسین در دنیا و آخرت نزد خودم آبرومندم قرار ده. ای اباعبدالله، من با دوستی و پیروی از تو به خدا و رسولش و امیرمؤمنان و فاطمه و حسن و تو نزدیک می‌شوم؛ و از کسانی که با تو جنگیدند و بر تو ستم روا داشتند بیزاری می‌جویم. از خدا و رسولش نیز از آنان که بنیان ستم بر شما و پیروانتان را گذاشتند بیزاری می‌جویم. من از آنان نزد خدا و شما بیزارم و با دوستی شما و دوستانتان به خدا و سپس به شما تقرب می‌جویم؛ و از دشمنانتان و کسانی که با شما جنگیدند و پیروانشان بیزاری می‌جویم. با دوستداران شما دوستم و با دشمنانتان دشمنم. از خدایی که شناخت شما و دوستانتان را روزی‌ام کرد و بیزاری از دشمنانتان را نصیبم ساخت، می‌خواهم که در دنیا و آخرت مرا با شما قرار دهد، گامم را نزد شما استوار بدارد، مرا به مقام پسندیده شما نزد خدا برساند و توفیق خون‌خواهی شما را همراه پیشوایی هدایتگر و آشکار که به حق سخن می‌گوید عطا کند. از خدا به حق شما و منزلتی که نزد او دارید می‌خواهم بهترین پاداش مصیبت‌دیدگان را در برابر این مصیبت بزرگ که در اسلام و همه آسمان‌ها و زمین عظیم است به من عطا فرماید.

خدایا، مرا در این جایگاه از کسانی قرار ده که درود و رحمت و آمرزش تو شامل حالشان می‌شود. خدایا، زندگی‌ام را زندگی محمد و خاندان محمد و مرگم را مرگ محمد و خاندان محمد قرار ده. خدایا، این روزی است که بنی‌امیه و فرزند زن جگرخوار از آن شادمان شدند؛ همان ملعونِ فرزند ملعون که بر زبان تو و پیامبرت در هر جایگاه و موضعی مورد لعن قرار گرفته است.

خدایا، ابوسفیان و معاویه و یزید بن معاویه را لعنت کن؛ لعنتی همیشگی. این روزی است که خاندان زیاد و مروان از کشتن حسین (درود خدا بر او) شاد شدند. خدایا، لعنت و عذاب دردناک خود را بر آنان چندین برابر کن.

خدایا، من در این روز و در این جایگاه و در همه روزهای زندگی‌ام، با بیزاری از آنان و لعنت بر ایشان و با دوستی پیامبرت و خاندان پیامبرت به تو تقرب می‌جویم؛ درود خدا بر او و بر آنان باد.''';
  }

  if (source.startsWith('اللَّهُمَّ الْعَنْ أَوَّلَ ظَالِمٍ')) {
    return '''خدایا، نخستین ستمگری را که به حق محمد و خاندان محمد ستم کرد و نیز آخرین کسی را که در این راه از او پیروی کرد، از سوی من لعنت کن. خدایا، گروهی را که با حسین جنگیدند و در کشتن او همراهی و بیعت کردند و از آنان پیروی نمودند، همگی لعنت کن.''';
  }
  if (source.startsWith('السَّلَامُ عَلَيْكَ يَا أَبَا عَبْدِ اللهِ وَعَلَى الْأَرْوَاحِ')) {
    return '''سلام بر تو ای اباعبدالله و بر جان‌هایی که در آستانت فرود آمدند. تا زمانی که زنده‌ام و شب و روز برقرار است، سلام خدا از سوی من بر تو باد؛ و خدا این زیارت را آخرین دیدار من با شما قرار ندهد. سلام بر حسین و بر علی بن الحسین و فرزندان حسین و یاران حسین.''';
  }
  if (source.startsWith('اللَّهُمَّ خُصَّ أَنْتَ أَوَّلَ ظَالِمٍ')) {
    return '''خدایا، نخستین ستمگر را از سوی من به لعنت ویژه کن و نخست از او آغاز فرما؛ سپس دومی و سومی و چهارمی را لعنت کن. خدایا، یزید را در مرتبه پنجم لعنت کن؛ و عبیدالله بن زیاد و ابن‌مرجانه و عمر بن سعد و شمر و خاندان ابوسفیان و خاندان زیاد و خاندان مروان را تا روز قیامت لعنت فرما.''';
  }
  if (source.startsWith('اللَّهُمَّ لَكَ الْحَمْدُ حَمْدَ الشَّاكِرِينَ')) {
    return '''خدایا، ستایش از آنِ توست؛ ستایش سپاسگزاران بر مصیبتی که بر آنان رسیده است. سپاس خدای را بر بزرگی مصیبتم. خدایا، شفاعت حسین را در روز ورود به محشر روزی‌ام کن و گامم را نزد خودت همراه حسین و یاران حسین استوار بدار؛ همان کسانی که جان‌های خود را در راه حسین فدا کردند.''';
  }

  if (source.startsWith('زيارة الامام العباس')) {
    return '''زیارت امام عباس (علیه‌السلام)

سلام خدا و فرشتگان مقرّبش و پیامبران فرستاده‌اش و بندگان شایسته‌اش و همه شهیدان و راست‌کرداران بر تو باد؛ و درودهای پاک و پاکیزه در هر بامداد و شامگاه بر تو باد، ای فرزند امیرمؤمنان. گواهی می‌دهم که در برابر جانشین پیامبر فرستاده‌شده، نواده برگزیده، راهنمای دانا، وصیّ رساننده پیام و مظلوم ستمدیده، اهل تسلیم و تصدیق و وفاداری و خیرخواهی بودی. خداوند از سوی پیامبرش و امیرمؤمنان و فاطمه و حسن و حسین، بهترین پاداش را به تو عطا کند؛ به پاس شکیبایی و طلب خشنودی خدا و یاری‌ات؛ چه نیکوست سرانجام آخرت. خدا لعنت کند کسی را که تو را کشت و کسی را که حق تو را نشناخت و حرمتت را سبک شمرد و میان تو و آب فرات فاصله انداخت. گواهی می‌دهم که مظلومانه کشته شدی و خدا وعده‌ای را که به شما داده است به انجام خواهد رساند. ای فرزند امیرمؤمنان، با دلی تسلیم و پیرو به سوی شما آمده‌ام؛ پیرو شما هستم و یاری‌ام برای شما آماده است تا خداوند داوری کند که او بهترین داوران است. من با شمایم، نه با دشمنانتان. به شما و بازگشتتان ایمان دارم و از مخالفان و قاتلانتان بیزارم. خدا مردمی را که شما را با دست‌ها و زبان‌هایشان کشتند نابود سازد.

سپس وارد شو و بر قبر خم شو و بگو:

سلام بر تو ای بنده شایسته‌ای که فرمان‌بردار خدا و رسول او و امیرمؤمنان و حسن و حسین بودی. سلام و رحمت و برکات و آمرزش و خشنودی خدا بر تو و بر جان و پیکرت باد. گواهی می‌دهم که راهی را پیمودی که مجاهدان بدر و رزمندگان راه خدا پیمودند؛ آنان که در جهاد با دشمنان خدا خیرخواه بودند، در یاری دوستان خدا کوشیدند و از محبوبان او دفاع کردند. خدا بهترین و کامل‌ترین پاداش را به تو عطا فرماید؛ پاداش کسی که به پیمان خود وفا کرد و دعوت را پذیرفت و از اولیای امر خویش فرمان برد. گواهی می‌دهم که در خیرخواهی کوتاهی نکردی و نهایت تلاش خود را به کار بردی. خدا تو را در شمار شهیدان قرار داد، روحت را با ارواح سعادتمندان همراه ساخت، در بهشت جایگاهی فراخ و منزلتی برتر به تو بخشید، نامت را در بلندمرتبگان جای داد و تو را با پیامبران و راست‌کرداران و شهیدان و شایستگان محشور کرد؛ و آنان چه نیکو همراهانی هستند. گواهی می‌دهم که سستی نورزیدی و عقب ننشستی و با آگاهی و بصیرت راه خود را برگزیدی و از شایستگان و پیامبران پیروی کردی. خدا ما را در جایگاه فروتنان با تو و پیامبرش و اولیایش گرد آورد؛ که او مهربان‌ترین مهربانان است.

سپس به سوی سر مبارک برو، دو رکعت نماز بخوان و این دعا را بخوان:

خدایا، بر محمد و خاندان محمد درود فرست و در این مکان گرامی و مشهد بزرگ، هیچ گناهی برایم باقی مگذار مگر آنکه بیامرزی؛ هیچ اندوهی مگر آنکه برطرف کنی؛ هیچ بیماری مگر آنکه شفا دهی؛ هیچ عیبی مگر آنکه بپوشانی؛ هیچ روزی‌ای مگر آنکه گسترده سازی؛ هیچ ترسی مگر آنکه ایمنی بخشی؛ هیچ پراکندگی‌ای مگر آنکه سامان دهی؛ و هیچ غایبی مگر آنکه حفظ کنی و نزدیک گردانی. هیچ حاجتی از نیازهای دنیا و آخرت که خشنودی تو در آن و صلاح من در آن باشد باقی مگذار مگر آنکه برآورده سازی، ای مهربان‌ترین مهربانان.

سپس به سوی پاها بازگرد و بگو:

سلام بر تو ای ابوالفضل عباس بن امیرمؤمنان؛ سلام بر تو ای فرزند سرور اوصیا؛ سلام بر تو ای فرزند نخستین مسلمانان و پیشگام‌ترین آنان در ایمان و استوارترینشان در دین خدا و پاسدارترینشان از اسلام. گواهی می‌دهم که برای خدا و پیامبرش و برادرت خیرخواهی کردی؛ چه نیکو برادری بودی که یاری و همراهی کرد. خدا لعنت کند مردمی را که تو را کشتند، به تو ستم کردند و حرمت‌ها را درباره تو شکستند و حرمت اسلام را پایمال کردند. چه نیکو شکیبایی بودی؛ مجاهدی مدافع و یاوری استوار و برادری که از برادرش دفاع کرد و فرمان پروردگارش را پذیرفت و به پاداش بزرگ و ستایش نیکو رغبت داشت. خدا تو را به درجه پدرانت در باغ‌های پرنعمت ملحق سازد. خدایا، با امید پاداش و آمرزش و احسان فراوانت به زیارت اولیایت آمده‌ام. از تو می‌خواهم بر محمد و خاندان پاکش درود فرستی، روزی‌ام را به برکت آنان فراخ و زندگی‌ام را به برکت آنان پایدار کنی، زیارتم را پذیرفته و زندگی‌ام را پاکیزه گردانی، مرا در شمار گرامی‌داشتگان قرار دهی و از کسانی سازی که از زیارت جایگاه‌های محبوبانت کامیاب و پیروز بازمی‌گردند؛ در حالی که آمرزش گناهان و پوشاندن عیب‌ها و گشایش اندوه‌ها را به دست آورده‌اند. همانا تو شایسته پروا و آمرزشی.''';
  }

  if (source.startsWith('قَالَ الرَّيَّانُ بْنُ شَبِيبٍ:')) {
    return '''ریان بن شبیب می‌گوید: در نخستین روز ماه محرم بر امام رضا (علیه‌السلام) وارد شدم. ایشان فرمود: ای پسر شبیب، آیا روزه‌ای؟ گفتم: نه. فرمود: این روز همان روزی است که زکریا (علیه‌السلام) پروردگارش را خواند و گفت: ﴿رَبِّ هَبْ لِي مِنْ لَدُنْكَ ذُرِّيَّةً طَيِّبَةً إِنَّكَ سَمِيعُ الدُّعَاءِ﴾. خداوند دعایش را پذیرفت و به فرشتگان فرمان داد زکریا را ندا دهند: «در حالی که در محراب به نماز ایستاده بود، خداوند او را به یحیی بشارت داد». پس هر کس این روز را روزه بگیرد و سپس خداوند را بخواند، خداوند دعایش را همان‌گونه که دعای زکریا را پذیرفت، اجابت می‌کند.

سپس فرمود: ای پسر شبیب، محرم ماهی است که مردم جاهلیت به احترام آن، ستم و جنگ را حرام می‌دانستند؛ اما این امت حرمت ماه خود و حرمت پیامبرش را نشناخت. در همین ماه فرزندان پیامبر را کشتند، زنانش را به اسارت گرفتند و دارایی‌هایش را غارت کردند؛ خدا هرگز این کار را بر آنان نیامرزد.

ای پسر شبیب، اگر برای چیزی گریه می‌کنی، برای حسین بن علی بن ابی‌طالب (علیه‌السلام) گریه کن؛ زیرا او مظلومانه کشته شد و هجده مرد از خاندانش نیز همراه او به شهادت رسیدند که همانندی در زمین نداشتند. آسمان‌های هفت‌گانه و زمین‌ها برای شهادتش گریستند و چهار هزار فرشته برای یاری او به زمین فرود آمدند، اما دیدند که به شهادت رسیده است. آنان تا قیام قائم کنار قبر او پریشان و غبارآلود می‌مانند و از یاران او خواهند بود و شعارشان «ای خون‌خواهان حسین» است.

ای پسر شبیب، پدرم از پدرش و او از جدش برایم روایت کرد که هنگامی که جدّم حسین کشته شد، آسمان خون و خاک سرخ باراند.

ای پسر شبیب، اگر آن‌قدر بر حسین گریه کنی که اشک‌هایت بر گونه‌هایت جاری شود، خداوند هر گناه کوچک و بزرگ و کم و زیادی را که انجام داده‌ای می‌آمرزد.

ای پسر شبیب، اگر دوست داری خدا را دیدار کنی در حالی که گناهی بر عهده‌ات نباشد، حسین را زیارت کن.

ای پسر شبیب، اگر دوست داری در غرفه‌های ساخته‌شده بهشتی همراه پیامبر ساکن شوی، قاتلان حسین را لعنت کن.

ای پسر شبیب، اگر دوست داری پاداشی همانند پاداش شهیدان همراه حسین داشته باشی، هرگاه او را یاد کردی بگو: «ای کاش با آنان بودم تا به کامیابی بزرگی می‌رسیدم».

ای پسر شبیب، اگر دوست داری در درجات بلند بهشت همراه ما باشی، در اندوه ما اندوهگین و در شادی ما شادمان باش و به ولایت ما پایبند بمان؛ زیرا اگر کسی سنگی را دوست بدارد، خداوند روز قیامت او را با همان سنگ محشور می‌کند.

منبع اصلی: عیون أخبار الرضا و امالی شیخ صدوق.
